INSERT INTO `screening_matches` VALUES (1,'2026-06-11 23:17:26.998181','corp.disqual, sanction, wanted, export.control, role.pol, debarment, poi, role.rca, role.pep','{\"limit\": 5, \"responses\": {\"query-1\": {\"query\": {\"id\": null, \"schema\": \"Person\", \"properties\": {\"name\": [\"Vladimir Putin\"], \"country\": [\"ru\"]}}, \"total\": {\"value\": 4, \"relation\": \"eq\"}, \"status\": 200, \"results\": [{\"id\": \"Q7747\", \"match\": true, \"score\": 1.0, \"schema\": \"Person\", \"target\": true, \"caption\": \"Vladimir Putin\", \"datasets\": [\"base_de_donnees_principale\"], \"last_seen\": \"2026-04-05T18:44:50\", \"referents\": [\"ch-seco-49812\", \"ua-ws-person-880\", \"usgsa-s4mrtyd57\", \"ja-mof-1e45d73d4aefd473f51cc8bb96061a16984b96c0\", \"gb-coh-cotyy6jdakw2xbkbahhn-4zovfs\", \"eu-fsf-eu-7510-16\", \"au-dfat-6678-vladimir-vladimirovich-putin\", \"be-fod-b5e4ab64639c9c7f869afedda014858f5700f5a5\", \"mc-freezes-e70429b07b7edc46d5667118dc5a59c4dd84ac1c\", \"lv-sanction-7e183b3d29abc48d6e71baf614c3b5132e98ee54\", \"eu-oj-e31802b61236f88412313c82e838a835aa174865\", \"eu-oj-d65e31ca4e1b1990211a63108c507e51633ad0df\", \"gb-hmt-14196\", \"ch-seco-8be1b1cbdf04edeca5dd8dba8f0da22dc84eb168\", \"ua-ws-856ff7ef3fefa0ff88edc5754e35d1afe6551049\", \"ch-seco-ac221e105ee1eaec78a4596c46b8b62d544b823b\", \"nz-ru-ind-1-vladimir-putin\", \"acf-39b7a17a53441b22846dfafcef974c7a28204672\", \"unprot-32bf82971599eb954c89ea33a205527cd2038596\", \"usgsa-s4mrky6qp\", \"ca-sema-60e89a4901773522fb01725b0d3302f2e6dba62c\", \"tw-shtc-9df27dced12904cbcc9a53219b6231801f4b6d9c\", \"fr-ga-4271\", \"us-cia-russia-vladimir-vladimirovich-putin-president\", \"tw-shtc-3c50f625574dd3f9403a9f24f0b515913953c51f\", \"unprot-8b1ac4ae93075a7bfb6745d9c5e3e8fa852fcdc0\", \"gb-fcdo-rus0251\", \"ltfiu-sanctioned-vladimir-vladimirovich-putin\", \"ua-nsdc-16102-putin-volodimir-volodimirovic\", \"ofac-35096\", \"ofac-pr-f8c86694458c59b06d2c188ae313b2e4357939a0\", \"usgsa-519971a04ac2cf7e4d2cb68a78bbe2a82